import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.CWpttWmj.js";const m=JSON.parse('{"title":"Registering a name","description":"","frontmatter":{},"headers":[],"relativePath":"guide/registering.md","filePath":"guide/registering.md","lastUpdated":null}'),r={name:"guide/registering.md"};function n(o,e,d,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="registering-a-name" tabindex="-1">Registering a name <a class="header-anchor" href="#registering-a-name" aria-label="Permalink to &quot;Registering a name&quot;">​</a></h1><p>Registration is deliberately a two-transaction process. This page explains what each transaction does, why the wait between them exists, and every way the process can fail.</p><p>For the short version, see <a href="/docs/guide/quick-start.html">Quick start</a>.</p><h2 id="why-two-transactions" tabindex="-1">Why two transactions <a class="header-anchor" href="#why-two-transactions" aria-label="Permalink to &quot;Why two transactions&quot;">​</a></h2><p>If registration were a single transaction, it would be trivially front-runnable. Your transaction sits in the public mempool before it is mined, naming the exact name you want. Anyone watching can copy it, pay more gas, and have their transaction mined first. You lose the name and still pay gas.</p><p>Arc Names uses <strong>commit-reveal</strong> to close this. The name is split across two transactions, and the first one gives nothing away.</p><h3 id="transaction-1-—-commit" tabindex="-1">Transaction 1 — commit <a class="header-anchor" href="#transaction-1-—-commit" aria-label="Permalink to &quot;Transaction 1 — commit&quot;">​</a></h3><p>Your browser generates a random 32-byte secret and hashes it together with the name and the owner address:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">makeCommitment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm, owner, secret)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> keccak256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">abi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">encode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keccak256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm)), owner, secret))</span></span></code></pre></div><p>Only that hash goes on-chain, via <code>commit(bytes32)</code>. The contract stores the current timestamp against it. An observer sees a 32-byte hash and cannot invert it — the secret makes brute-forcing candidate names useless.</p><h3 id="the-wait" tabindex="-1">The wait <a class="header-anchor" href="#the-wait" aria-label="Permalink to &quot;The wait&quot;">​</a></h3><p><code>register</code> requires that <code>minCommitAge</code> has elapsed since the commit:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(commitments[c] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> minCommitAge </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.timestamp, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;early&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(commitments[c] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxCommitAge  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.timestamp, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;commit expired&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The minimum guarantees your commitment is already settled in a past block before the name becomes public knowledge. By the time a front-runner learns what you wanted, they&#39;d need a commitment older than yours, and they don&#39;t have one.</p><p>The maximum stops commitments accumulating in storage forever, and stops someone from hoarding a cheap option on a name indefinitely.</p><p>Both values are set by the contract owner via <code>setLimits</code> and can change. The app reads them live and shows the actual countdown — don&#39;t hardcode them.</p><h3 id="transaction-2-—-register" tabindex="-1">Transaction 2 — register <a class="header-anchor" href="#transaction-2-—-register" aria-label="Permalink to &quot;Transaction 2 — register&quot;">​</a></h3><p><code>register(name, owner, duration, secret)</code> reveals the name and the secret. The contract recomputes the commitment hash, checks the timing, validates the name, takes payment, and mints.</p><p>There is also a five-argument overload that takes a referrer — see <a href="#referrals">Referrals</a>.</p><h2 id="what-registration-actually-does" tabindex="-1">What registration actually does <a class="header-anchor" href="#what-registration-actually-does" aria-label="Permalink to &quot;What registration actually does&quot;">​</a></h2><p>The mint is not just an NFT. <code>_doRegister</code> → <code>_mint</code> performs, in one transaction:</p><ol><li><code>registrar.register(id, controller, duration)</code> — mints the ERC-721 and sets the expiry.</li><li><code>ens.setResolver(node, resolver)</code> — binds the default resolver to your name.</li><li><code>resolver.setAddr(node, owner)</code> — points the name at the owner&#39;s address.</li><li><code>registrar.reclaim(id, owner)</code> — writes you as the registry owner of the node.</li><li><code>registrar.transferFrom(controller, owner, id)</code> — transfers the token to you.</li></ol><p>So a freshly registered name <strong>already resolves to your address</strong>. You do not need to set a resolver or an address record afterwards. What is <em>not</em> set automatically is the reverse record — see <a href="/docs/guide/primary-name.html">Your primary name</a>.</p><p>It emits <code>NameRegistered(name, label, owner, cost, expiry)</code>.</p><h2 id="what-makes-a-name-valid" tabindex="-1">What makes a name valid <a class="header-anchor" href="#what-makes-a-name-valid" aria-label="Permalink to &quot;What makes a name valid&quot;">​</a></h2><p>There are two different sets of rules, and the difference matters.</p><h3 id="on-chain-rules" tabindex="-1">On-chain rules <a class="header-anchor" href="#on-chain-rules" aria-label="Permalink to &quot;On-chain rules&quot;">​</a></h3><p><code>ArcController.valid()</code> enforces only:</p><ul><li>Length is at least <code>minLen</code> (owner-configurable, and never below 2).</li><li>If the name is exactly 2 characters, a 2-character price must be configured.</li><li><strong>No uppercase ASCII</strong> (bytes <code>0x41</code>–<code>0x5A</code>).</li></ul><p>That is the entire on-chain check. It does not restrict the character set beyond rejecting uppercase — which means names containing Unicode, emoji, whitespace or invisible characters are registerable by anyone calling the contract directly.</p><h3 id="app-rules" tabindex="-1">App rules <a class="header-anchor" href="#app-rules" aria-label="Permalink to &quot;App rules&quot;">​</a></h3><p>The Arc Names app applies a stricter filter before it will let you register: lowercase letters, digits and hyphens only, no leading or trailing hyphen, maximum 63 characters.</p><div class="danger custom-block"><p class="custom-block-title">Names in the wild may not follow the app&#39;s rules</p><p>Because the on-chain check is looser, a name you see in the marketplace or in an activity feed may contain characters the app would never let you type — including ones that render identically to ASCII. Never judge a name by how it looks. See <a href="/docs/safety.html#look-alike-names">Safety → look-alike names</a>.</p></div><h2 id="duration" tabindex="-1">Duration <a class="header-anchor" href="#duration" aria-label="Permalink to &quot;Duration&quot;">​</a></h2><p>You pay per year, prorated to the second:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">price</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm, dur) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> usdPerYear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(length) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dur </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 365</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> days</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Bound</th><th>Value</th></tr></thead><tbody><tr><td>Minimum</td><td>28 days</td></tr><tr><td>Maximum</td><td>36,500 days (100 years)</td></tr></tbody></table><p>Anything outside that range reverts with <code>duration</code>. Registering for longer costs proportionally more but is still a single transaction, so a long registration saves gas and saves you from <a href="/docs/guide/renewals.html">forgetting to renew</a>.</p><h2 id="paying" tabindex="-1">Paying <a class="header-anchor" href="#paying" aria-label="Permalink to &quot;Paying&quot;">​</a></h2><p>The native gas token is USDC with 18 decimals, and the pricing is scaled so that <strong>1 USD of price is exactly 1e18 native wei</strong>. The number the contract returns from <code>price()</code> is the USD price directly, in wei.</p><p>Send at least <code>price()</code>. Sending less reverts with <code>underpaid</code>. Sending more is fine — the contract refunds the difference to <code>msg.sender</code> in the same transaction:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> due) { (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ok,) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.call{value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> due}(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ok); }</span></span></code></pre></div><p>The app deliberately quotes a small buffer over the exact price so that a price change between quote and mint doesn&#39;t fail your transaction. You are never charged the buffer.</p><p>There is also <code>registerManyUSDC</code> for paying with the 6-decimal ERC-20 USDC instead. See <a href="/docs/protocol/fees.html#two-kinds-of-usdc">Fees → two kinds of USDC</a>.</p><h2 id="registering-several-names-at-once" tabindex="-1">Registering several names at once <a class="header-anchor" href="#registering-several-names-at-once" aria-label="Permalink to &quot;Registering several names at once&quot;">​</a></h2><p><code>registerMany(names[], owner, duration)</code> registers between <strong>1 and 20</strong> names in one transaction, under a single commitment. More than 20 reverts with <code>count</code>. Every name must be valid and every name must be available — one bad name reverts the whole batch.</p><h2 id="referrals" tabindex="-1">Referrals <a class="header-anchor" href="#referrals" aria-label="Permalink to &quot;Referrals&quot;">​</a></h2><p>The controller supports referral attribution natively. The five-argument overload:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm, owner, duration, secret, referrer)</span></span></code></pre></div><p>When a referrer is supplied, the contract applies two independent basis-point rates:</p><table tabindex="0"><thead><tr><th>Rate</th><th>Who benefits</th><th>Effect</th></tr></thead><tbody><tr><td><code>refDiscountBps</code></td><td>The registrant</td><td><code>due = base - base * refDiscountBps / 10000</code></td></tr><tr><td><code>refRewardBps</code></td><td>The referrer</td><td>Paid <code>base * refRewardBps / 10000</code></td></tr></tbody></table><p>Each is capped at 2000 bps (20%) and both default to zero, so referrals are inert until the owner enables them via <code>setReferral</code>.</p><p>The referrer is ignored — and full price charged — if it is the zero address, the caller, or the name&#39;s owner. This stops self-referral.</p><p>If paying the referrer fails (a contract that rejects transfers, say), the reward is credited to <code>pendingWithdrawals[referrer]</code> and can be pulled later with <code>withdrawPending()</code>. Either way a <code>ReferralPaid(referrer, buyer, amount)</code> event is emitted, which makes an on-chain referral leaderboard straightforward to build.</p><div class="info custom-block"><p class="custom-block-title">Not yet wired into the app</p><p>The referral overload exists in the deployed controller but the Arc Names frontend currently calls the four-argument <code>register</code>. Integrators calling the contract directly can use it today.</p></div><h2 id="keeping-your-secret-safe" tabindex="-1">Keeping your secret safe <a class="header-anchor" href="#keeping-your-secret-safe" aria-label="Permalink to &quot;Keeping your secret safe&quot;">​</a></h2><p>The secret lives in your browser&#39;s local storage under <code>arc:pending-commitments:v2</code> between the two transactions.</p><p>If you lose it — clearing site data, switching browsers, using a private window that closes — the commitment cannot be revealed. It isn&#39;t a loss of funds beyond the commit gas, but you must start over and wait out <code>minCommitAge</code> again. The name is not reserved for you in the meantime.</p><h2 id="registration-states" tabindex="-1">Registration states <a class="header-anchor" href="#registration-states" aria-label="Permalink to &quot;Registration states&quot;">​</a></h2><p>The app models the flow as an explicit state machine, which is what the progress indicator reflects:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>idle</code></td><td>Nothing in progress.</td></tr><tr><td><code>committing</code></td><td>Commit transaction sent, waiting for confirmation.</td></tr><tr><td><code>waiting</code></td><td>Commit confirmed, <code>minCommitAge</code> countdown running.</td></tr><tr><td><code>ready</code></td><td>Countdown finished; register is now callable.</td></tr><tr><td><code>registering</code></td><td>Register transaction sent.</td></tr><tr><td><code>complete</code></td><td>Name minted.</td></tr><tr><td><code>expired</code></td><td><code>maxCommitAge</code> passed before you registered. Start over.</td></tr></tbody></table><h2 id="revert-reference" tabindex="-1">Revert reference <a class="header-anchor" href="#revert-reference" aria-label="Permalink to &quot;Revert reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Revert</th><th>Cause</th></tr></thead><tbody><tr><td><code>early</code></td><td>You called <code>register</code> before <code>minCommitAge</code> elapsed. Wait for the countdown.</td></tr><tr><td><code>commit expired</code></td><td>More than <code>maxCommitAge</code> passed since the commit. Start over.</td></tr><tr><td><code>committed</code></td><td>You committed the same hash again while a live commitment exists.</td></tr><tr><td><code>invalid</code></td><td>The name fails <code>valid()</code> — too short, uppercase, or a 2-char name with no price set.</td></tr><tr><td><code>duration</code></td><td>Duration outside 28 days – 100 years.</td></tr><tr><td><code>underpaid</code></td><td><code>msg.value</code> below the quoted price.</td></tr><tr><td><code>owner</code></td><td>Owner address is the zero address.</td></tr><tr><td><code>taken</code></td><td>The name is registered, or expired but still in its 90-day grace period.</td></tr><tr><td><code>short</code></td><td>Requested price for a name shorter than <code>minLen</code>.</td></tr><tr><td><code>2char</code></td><td>Two-character name while <code>price2</code> is zero — 2-char names are disabled.</td></tr><tr><td><code>count</code></td><td><code>registerMany</code> called with 0 names, or more than 20.</td></tr><tr><td><code>!live</code></td><td>The registrar no longer controls the <code>.arc</code> node. A protocol-level fault; nothing you can fix.</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/pricing.html">Pricing &amp; rarity</a> — how length determines cost.</li><li><a href="/docs/guide/renewals.html">Renewals &amp; expiry</a> — keeping the name.</li><li><a href="/docs/guide/records.html">Records &amp; profile</a> — filling in the profile.</li></ul>`,65)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
